------------ lifeCycle ------------


function SettingVoiceBtnGroup:CleanProperties()
    self.btnNode = nil
    self.btnsRoot = nil
    self.btnsMap = nil
    self.curVoice = nil
    
    self.eventVoiceStateChanged = nil
    self.eventVoiceCountChanged = nil
end

function SettingVoiceBtnGroup:RegistEvents()
    self.eventVoiceStateChanged = Events.AddListener(Constants.EventNames.SettingVoiceStateChanged, Bind(self, self.OnVoiceStateChanged))
    self.eventVoiceCountChanged = Events.AddListener(Constants.EventNames.SettingVoiceCountChanged, Bind(self, self.OnVoiceCountChanged))
end

function SettingVoiceBtnGroup:UnregistEvents()
    Events.RemoveListener(Constants.EventNames.SettingVoiceStateChanged, self.eventVoiceStateChanged)
    Events.RemoveListener(Constants.EventNames.SettingVoiceCountChanged, self.eventVoiceCountChanged)
end

function SettingVoiceBtnGroup:InitBtns(btnNode, btnsRoot)
    local LocalizeVoiceList = SettingVoiceMgr.LocalizeVoiceList
    local curVoice = SettingVoiceMgr:GetCurrentVoiceTag()
    self.btnNode = btnNode
    self.btnsRoot = btnsRoot
    self.curVoice = curVoice

    self.btnsMap = {}
    for i, voiceInfo in ipairs(LocalizeVoiceList) do
        local voiceTag = voiceInfo.voiceTag
        local voiceName = voiceInfo.GetVoiceName()
        local btnVoice = CS.UnityEngine.GameObject.Instantiate(self.btnNode.gameObject, self.btnsRoot, false)
        local LB_Btn = GetLuaBehaviour(btnVoice, "Game.UI.Setting.SettingVoiceBtn")
        LB_Btn.Env:InitBtn(voiceTag, voiceName, function()
            for k, v in pairs(self.btnsMap) do
                v.LT_Btn:SetSelected(false)
            end
        end)
        self.btnsMap[voiceTag] = { name = voiceInfo.GetVoiceName, LT_Btn = LB_Btn.Env }
        if voiceTag == curVoice then
            LB_Btn.Env:SetSelected(true)
        end
        KTool.SetActive(btnVoice, true)
    end
end

function SettingVoiceBtnGroup:RefreshBtns()
    for k, btnInfo in pairs(self.btnsMap) do
        btnInfo.LT_Btn:RefreshName(btnInfo.name())
    end
end

function SettingVoiceBtnGroup:OnVoiceStateChanged(voiceTag, state)
    for tag, btn in pairs(self.btnsMap) do
        if tag == voiceTag then
            local LT_Btn = self.btnsMap[voiceTag].LT_Btn
            LT_Btn:OnVoiceStateChanged(state)
        end
    end
end

function SettingVoiceBtnGroup:OnVoiceCountChanged(voiceTag, count)
    for tag, btn in pairs(self.btnsMap) do
        if tag == voiceTag then
            local LT_Btn = self.btnsMap[voiceTag].LT_Btn
            LT_Btn:OnVoiceCountChanged(count)
        end
    end
end

return SettingVoiceBtnGroup